css:
.receipt {
  width: 250px;
  background: white;
  border: 2px dashed #ccc;
  padding: 15px;
  border-radius: 8px;
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.2);
}

.shop-name {
  font-size: 1.2rem;
  font-weight: bold;
  text-align: center;
  margin-bottom: 10px;
}

.info {
  text-align: center;
  font-size: 0.85rem;
  margin-bottom: 15px;
}

.receipt table {
  width: 100%;
  border-collapse: collapse;
  margin-bottom: 15px;
  font-size: 0.85rem;
}

.receipt table th,
.receipt table td {
  padding: 4px;
  text-align: left;
  border-bottom: 1px solid #eee;
}

.total {
  display: flex;
  justify-content: space-between;
  font-size: 1rem;
  font-weight: bold;
  margin-bottom: 15px;
}

.barcode {
  display: flex;
  justify-content: center;
  margin-top: 15px;
}

.thanks {
  font-size: 0.85rem;
  text-align: center;
  margin-top: 10px;
}
